const rawItemIds = {{workflowparams:item_id}};

// Accept a scalar id as well as the array form, matching Build Descriptions.
let requested = [];
if (Array.isArray(rawItemIds)) requested = rawItemIds;
else if (rawItemIds != null && rawItemIds !== "") requested = [rawItemIds];

// Digits only: these ids are interpolated into Get Items' SQL.
const itemIDs = [...new Set(requested.map((v) => String(v == null ? "" : v).trim()))].filter(
  (id) => /^[0-9]+$/.test(id)
);

return { itemIdCsv: itemIDs.join(',') };

const rows = {{node:sql_node_ItemBinds.data}} || [];
const rawItemIds = {{workflowparams:item_id}};
const customerId = {{workflowparams:customer_id}};

// sql-node rows sit at .data, and one row comes back bare rather than in an array.
const items = Array.isArray(rows) ? rows : (rows ? [rows] : []);

// Get Items returns table_cust_item_bind as a JSON_ARRAYAGG string.
const parseBinds = (v) => {
  if (Array.isArray(v)) return v;
  if (!v) return [];
  try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; }
};

const itemById = {};
for (const r of items) {
  if (r && r.id != null)
    itemById[String(r.id)] = { ...r, table_cust_item_bind: parseBinds(r.cust_item_bind_json) };
}

// Accept a scalar id as well as the array form, so a caller passing a plain
// string still works.
let requested = [];
if (Array.isArray(rawItemIds)) requested = rawItemIds;
else if (rawItemIds != null && rawItemIds !== "") requested = [rawItemIds];

const wanted = customerId == null ? "" : String(customerId).trim();

// table_cust_item_bind is a subform array stored on the Item record itself --
// it has no collection of its own, so the single Item search above is all the
// data access needed. Bind rows store the Customer's primary id; compare as
// trimmed strings.
const buildDescriptions = (item) => {
  const out = [];
  if (!item) return out;
  const binds = Array.isArray(item.table_cust_item_bind) ? item.table_cust_item_bind : [];
  for (const row of binds) {
    if (!row) continue;
    const rowCust = row.customer_id == null ? "" : String(row.customer_id).trim();
    if (!wanted || rowCust !== wanted) continue;
    const d = row.item_desc == null ? "" : String(row.item_desc).trim();
    // One customer may have several rows; skip blanks and duplicates.
    if (d && out.indexOf(d) === -1) out.push(d);
  }
  // No customer-specific description -> fall back to the item's own description.
  if (out.length === 0) {
    const fallback = item.material_desc == null ? "" : String(item.material_desc).trim();
    if (fallback) out.push(fallback);
  }
  return out;
};

// One row per REQUESTED id, in request order -- an id matching no Item still
// gets an entry with an empty list, so callers can map by index or by id.
// descCache keeps a repeated id from being rebuilt.
const descCache = {};
const result = [];
for (const raw of requested) {
  const id = raw == null ? "" : String(raw).trim();
  if (!id) {
    result.push({ item_id: "", descriptions: [] });
    continue;
  }
  if (!descCache[id]) descCache[id] = buildDescriptions(itemById[id]);
  result.push({ item_id: id, descriptions: descCache[id] });
}

return { result };
